'use strict';
(function(root){
 const bi=(zh,en)=>({zh,en});
 function create(atlas,catalog,design){
  const protocols=new Map((atlas.documentedTasks||[]).filter(u=>u.origin!=='arena-documented-candidate').map(u=>[u.id,u]));
  const records=new Map([...atlas.records,...atlas.gameCatalogRecords].map(r=>[r.id,r]));
  const byId=new Map(),byProtocol=new Map(),bindings=new Map(design.bindings.map(b=>[b.id,b]));
  for(const t of catalog.tasks){const b=bindings.get(t.id),p=protocols.get(b?.protocolId);if(!p||p.benchmark!==t.benchmark||!p.gameIds.includes(t.game))throw Error('Invalid Arena protocol reference: '+t.id);
   const task={...t,...b,protocol:p,title:p.label,scope:p.task,metric:p.metrics,controls:p.controls,interface:{zh:p.observation.zh+' / '+p.action.zh,en:p.observation.en+' / '+p.action.en},secondary:t.secondary.filter(c=>c!==b.primary),sources:p.evidence,runnable:false};
   byId.set(t.id,task);byProtocol.set(p.id,task);
  }
  for(const p of protocols.values())if(!byProtocol.has(p.id)){const primary=p.capabilities.find(c=>c.role==='primary')?.id||null;const t={id:'protocol:'+p.id,protocolId:p.id,benchmark:p.benchmark,game:p.gameIds[0],title:p.label,protocol:p,scope:p.task,metric:p.metrics,controls:p.controls,primary,secondary:p.capabilities.filter(c=>c.id!==primary).map(c=>c.id),track:'unspecified',mechanism:null,mechanismLabel:bi('机制尚未编目','Mechanism not catalogued'),question:bi('按任务目标确定研究问题','Define the question from the task objective'),confounds:p.limits,design:bi('按来源配置后纳入组合。','Configure from the source before inclusion.'),diagnostic:bi('按原始指标报告。','Report native metrics.'),sources:p.evidence,runnable:false};byId.set(t.id,t);byProtocol.set(p.id,t);}
  function get(id){return byId.get(id)||byProtocol.get(String(id).replace(/^protocol:/,''));}
  const select=ids=>[...new Map((Array.isArray(ids)?ids:[]).map(get).filter(Boolean).map(t=>[t.protocolId,t])).values()];
  const relationTypes={duplicate:bi('重复收录','Duplicate'),alternative:bi('可替代','Alternative'),contrast:bi('控制对照','Controlled contrast'),complementary:bi('互补','Complementary')};
  function relations(ids){const selected=new Set(select(ids).map(t=>t.id));return design.relations.filter(r=>r.tasks.every(id=>selected.has(id))).map(r=>({...r,sources:[...new Map(r.protocolIds.flatMap(id=>protocols.get(id)?.evidence||[]).map(s=>[s.url,s])).values()]}));}
  function coverage(ids){const tasks=select(ids),axes=(atlas.taskDimensions||catalog.dimensions).map(d=>({...d,primary:tasks.filter(t=>t.primary===d.id).map(t=>t.id),secondary:tasks.filter(t=>t.secondary.includes(d.id)).map(t=>t.id)}));return {selected:tasks,axes,covered:axes.filter(a=>a.primary.length).length,gaps:axes.filter(a=>!a.primary.length).map(a=>a.id),benchmarks:[...new Set(tasks.map(t=>t.benchmark))],runnable:0};}
  function analysis(ids,target=[]){const c=coverage(ids),mechanisms=[...new Map(c.selected.filter(t=>t.mechanism).map(t=>[t.mechanism,{id:t.mechanism,label:t.mechanismLabel,tasks:c.selected.filter(x=>x.mechanism===t.mechanism).map(x=>x.id)}])).values()];const tracks=[...new Set(c.selected.map(t=>t.track))];return {...c,mechanisms,relations:relations(ids),tracks,targetGaps:target.filter(id=>!c.axes.find(a=>a.id===id)?.primary.length),unclassified:c.selected.filter(t=>!t.mechanism).map(t=>t.id),needsConfiguration:c.selected.map(t=>({id:t.id,controls:t.protocol.controls,version:t.protocol.protocolDetails?.version||null,budget:t.protocol.protocolDetails?.budget||null}))};}
  function delta(ids,id){const t=get(id);if(!t)return null;const others=select(ids).filter(x=>x.id!==t.id),included=select(ids).some(x=>x.id===t.id);return {included,newMechanism:!!t.mechanism&&!others.some(x=>x.mechanism===t.mechanism),uniquePrimary:!!t.primary&&!others.some(x=>x.primary===t.primary),relations:relations([...others.map(x=>x.id),t.id]).filter(r=>r.tasks.includes(t.id))};}
  function pair(a,b){a=get(a);b=get(b);if(!a||!b)return null;if(a.protocolId===b.protocolId)return {type:'duplicate',summary:bi('引用同一个任务协议，按一个评测单元计数。','Both reference the same task protocol; count one evaluation unit.')};return relations([a.id,b.id])[0]||{type:'unreviewed',summary:bi('该任务对尚无专项关系判断；请比较机制与实验条件。','This pair has no curated relationship assessment; compare mechanisms and conditions.')};}
  function manifest(ids,settings={},templateId=null){const tasks=select(ids);if(!tasks.length)throw Error('Select at least one task');const template=design.templates.find(t=>t.id===templateId),a=analysis(ids,template?.targetCapabilities||[]);return {schema:'atlas-arena-plan-v2',designVersion:design.schemaVersion,checkedAt:design.checkedAt,template:template?.id||null,status:'planning-only',ready:false,results:[],tasks:tasks.map(t=>({id:t.id,protocolId:t.protocolId,benchmark:t.benchmark,game:t.game,question:t.question,mechanism:t.mechanismLabel,role:template?.roles[t.id]||null,sourceProtocol:t.protocol,design:t.design,confounds:t.confounds,configuration:settings[t.id]||{},executionVerified:false})),analysis:{mechanisms:a.mechanisms,relations:a.relations,tracks:a.tracks,targetGaps:a.targetGaps},reporting:bi('在相同任务、接口、训练与预算条件下比较 Agent；分别报告任务原始指标与不确定性。','Compare agents within matched task, interface, training and budget conditions; report native metrics and uncertainty separately.')};}
  function markdown(plan,lang='zh'){const tr=x=>typeof x==='string'?x:x?.[lang]||x?.en||'',lines=[`# ${lang==='zh'?'Game Arena 评测方案':'Game Arena evaluation plan'}`,`\n${tr(plan.reporting)}`,`\n${lang==='zh'?'方案版本':'Design version'}: ${plan.designVersion}`];for(const t of plan.tasks){lines.push(`\n## ${tr(t.sourceProtocol.label)}`,`\n${t.benchmark} · ${t.protocolId}`,`\n${tr(t.question)}`,`\n${tr(t.design)}`);for(const [key,label]of Object.entries({task:bi('任务','Task'),observation:bi('观测','Observation'),action:bi('动作','Actions'),metrics:bi('原始指标','Native metrics'),controls:bi('来源配置','Source configuration'),limits:bi('范围','Scope')}))lines.push(`\n**${tr(label)}**: ${tr(t.sourceProtocol[key])}`);for(const [k,v] of Object.entries(t.sourceProtocol.protocolDetails||{}))if(tr(v))lines.push(`\n**${k}**: ${tr(v)}`);if(t.role)lines.push(`\n**${lang==='zh'?'组合分工':'Role in suite'}**: ${tr(t.role)}`);lines.push(`\n**${lang==='zh'?'主要干扰因素':'Principal confounds'}**: ${tr(t.confounds)}`);lines.push(`\n**${lang==='zh'?'本次实验配置':'Experiment configuration'}**`);for(const [k,v] of Object.entries(t.configuration))if(v)lines.push(`- ${k}: ${v}`);if(!Object.values(t.configuration).some(Boolean))lines.push(lang==='zh'?'尚未填写。':'Not configured.');for(const s of t.sourceProtocol.evidence)lines.push(`- [${s.title}](${s.url})`);}for(const r of plan.analysis.relations)lines.push(`\n## ${tr(relationTypes[r.type])}: ${r.tasks.join(' / ')}`,tr(r.summary),tr(r.difference),tr(r.recommendation));return lines.join('\n')+'\n';}
  return {get,select,coverage,analysis,delta,pair,relations,manifest,markdown,relationTypes,protocols,records,templates:design.templates,candidates:catalog.tasks.map(t=>get(t.id)),all:[...byId.values()]};
 }
 if(typeof module!=='undefined')module.exports={create};else root.AtlasEvaluationModel={create};
})(typeof window==='undefined'?{}:window);
